// Қосымша А: диагностикалық тапсырмалар мен бағалау рубрикасы.
const { data, p, center, h1, h2, bullet, tableTitle, codeBlock, table, makeDoc, save, spacer } = require("./common");

const letters = ["A", "B", "C", "D"];
const children = [];

children.push(center({ text: "Қосымша А", b: true }, { after: 60 }));
children.push(center({ text: "«JS-Тәлімгер» қосымшасының диагностикалық тапсырмалары мен бағалау рубрикасы", b: true }, { after: 200 }));

children.push(p("Диагностикалық модуль екі бөліктен тұрады: JavaScript негіздері бойынша 10 сұрақтық тест және код жазуды талап ететін үш практикалық тапсырма. Тест автоматты түрде бағаланады. Практикалық тапсырмаларға берілген жауаптарды ЖИ (Google Gemini) осы рубрика бойынша талдайды, ал соңғы бағаны педагог тексеріп бекітеді. Әр тапсырманың нұсқасы (version) жауаппен бірге сақталады: тапсырма мәтіні немесе рубрика өзгерсе, нұсқа нөмірі артады."));

// ---------- 1. Тест ----------
children.push(h1("1. Диагностикалық тест"));
children.push(p(`Мақсаты: білім алушының JavaScript негіздері бойынша бастапқы деңгейін анықтау. Әр сұраққа бір дұрыс жауап бар; дұрыс жауап — 1 балл, барлығы ${data.test.questions.length} балл. Тест нәтижесі тақырыптар бойынша сақталады, сондықтан зерттеуші қай тақырыпта қате жиі кездесетінін көре алады.`));
children.push(tableTitle("А.1-кесте – Тест сұрақтары, жауап нұсқалары және өлшенетін тақырып"));
children.push(table(
  ["№", "Сұрақ", "Жауап нұсқалары", "Дұрыс жауап", "Тақырып"],
  data.test.questions.map((q, i) => [
    { text: String(i + 1), center: true },
    q.text,
    q.options.map((o, j) => ({ text: `${letters[j]}) ${o}`, mono: true })),
    { text: `${letters[q.correct]}) ${q.options[q.correct]}`, mono: true },
    q.topic,
  ]),
  [450, 2900, 2555, 1600, 1850],
  { size: 22 },
));
children.push(spacer(60));
children.push(p("Тест нәтижесін түсіндіру шкаласы: 0–4 балл — төмен деңгей, 5–7 балл — орта деңгей, 8–10 балл — жоғары деңгей."));

// ---------- 2. Практикалық тапсырмалар ----------
children.push(h1("2. Практикалық тапсырмалар және рубрикалар"));
children.push(p("Әр практикалық тапсырма төрт критерий бойынша бағаланады, әр критерий 0–2 балл, барлығы 8 балл. Бағалау деңгейлерінің сипаттамасы ЖИ сұранысына да қосылады, сондықтан ЖИ мен педагог бірдей өлшемге сүйенеді. Код серверде орындалмайды, ол мәтін ретінде талданады."));

data.tasks.forEach((t, idx) => {
  children.push(h2(`2.${idx + 1}. ${t.task_id}. ${t.title}`));
  children.push(p([{ text: "Өлшенетін дағды: ", b: true }, t.skill]));
  children.push(p({ text: "Тапсырма мәтіні:", b: true }, { noIndent: true, keepNext: true }));
  children.push(...codeBlock(t.text, 24, true));
  children.push(p({ text: "Күтілетін жауап (педагогке арналған үлгі):", b: true }, { noIndent: true, keepNext: true, before: 120 }));
  children.push(...codeBlock(t.expected_answer));
  children.push(tableTitle(`А.${idx + 2}-кесте – ${t.task_id} тапсырмасының бағалау рубрикасы`));
  children.push(table(
    ["Критерий", "0 балл", "1 балл", "2 балл"],
    [
      ...t.criteria.map((c) => [c.name, c.levels[0], c.levels[1], c.levels[2]]),
      [{ text: "Барлығы", b: true }, "", "", { text: `${t.max_score} балл`, b: true }],
    ],
    [2755, 2200, 2200, 2200],
    { size: 22, firstColFill: true },
  ));
  children.push(p({ text: "Ықтимал қателер:", b: true }, { noIndent: true, keepNext: true, before: 120 }));
  t.typical_errors.forEach((e) => children.push(bullet(e)));
});

children.push(h1("3. Практикалық тапсырмалардың жалпы бағалау шкаласы"));
children.push(table(
  ["Балл (бір тапсырма)", "Деңгей", "Түсіндірме"],
  [
    ["0–3", "Төмен", "Негізгі ұғымдар меңгерілмеген, шешім жұмыс істемейді немесе тапсырмаға сай емес"],
    ["4–6", "Орта", "Шешімнің негізі дұрыс, бірақ шекаралық жағдайларда немесе түсіндірмеде қателер бар"],
    ["7–8", "Жоғары", "Шешім толық дұрыс, шекаралық жағдайлар ескерілген, түсіндірме қисынды"],
  ],
  [2300, 1500, 5555],
));
children.push(spacer(60));
children.push(p("ЖИ ұсынған балл автоматты түрде соңғы баға болып саналмайды: педагог оны «Зерттеуші бетінде» тексеріп, қажет болса түзетеді. ЖИ бағасы мен педагог бағасы деректер қорында бөлек сақталады."));

save(makeDoc(children), "Қосымша_А_Тапсырмалар_мен_рубрика.docx");
